def f(inputs: List[Tuple[int, int, int]]) -> List[int]:
    res = []
    for a, b, n in inputs:
        cnt = 0
        while b % a == 0:
            b //= a
            cnt += 1
        if b == 1:
            res.append(cnt)
        else:
            res.append(-1)
    return res
```

